import NextAuth from "next-auth";
import Credentials from "next-auth/providers/credentials";
import Google from "next-auth/providers/google";
import { authConfig } from "@/auth.config";
import { findOrCreateGoogleUser, verifyCredentials } from "@/lib/users";

export const { handlers, auth, signIn, signOut } = NextAuth({
  ...authConfig,
  session: { strategy: "jwt" },
  providers: [
    Google, // reads AUTH_GOOGLE_ID / AUTH_GOOGLE_SECRET
    Credentials({
      credentials: { email: {}, password: {} },
      async authorize(creds) {
        if (typeof creds?.email !== "string" || typeof creds?.password !== "string") return null;
        return (await verifyCredentials(creds.email, creds.password)) ?? null;
      },
    }),
  ],
  callbacks: {
    ...authConfig.callbacks,
    async signIn({ account, profile }) {
      if (account?.provider !== "google") return true;
      if (!profile?.sub || !profile.email) return false;
      const user = await findOrCreateGoogleUser({
        googleId: profile.sub,
        email: profile.email,
        emailVerified: profile.email_verified === true,
        name: profile.name,
      });
      if (!user) return false;
      account.userId = user.id; // consumed by jwt() below
      return true;
    },
    async jwt({ token, user, account }) {
      if (account?.provider === "google" && account.userId) token.sub = account.userId;
      else if (user?.id) token.sub = user.id;
      return token;
    },
    session({ session, token }) {
      if (token.sub) session.user.id = token.sub;
      return session;
    },
  },
});
EOF
