import { randomUUID, scrypt, randomBytes, timingSafeEqual } from "node:crypto";
import { promisify } from "node:util";

const scryptAsync = promisify(scrypt);

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

type UserRecord = User & { passwordHash?: string; googleId?: string };

// In-memory store (no database yet). Kept on globalThis so dev HMR doesn't wipe sign-ups.
const globalStore = globalThis as unknown as { __notelyUsers?: UserRecord[] };
const users: UserRecord[] = (globalStore.__notelyUsers ??= [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
]);

const normalizeEmail = (email: string) => email.trim().toLowerCase();

const toUser = ({ id, email, name, createdAt }: UserRecord): User => ({
  id,
  email,
  name,
  createdAt,
});

async function hashPassword(password: string): Promise<string> {
  const salt = randomBytes(16);
  const key = (await scryptAsync(password, salt, 64)) as Buffer;
  return `${salt.toString("hex")}:${key.toString("hex")}`;
}

async function checkPassword(password: string, stored: string): Promise<boolean> {
  const [saltHex, keyHex] = stored.split(":");
  const expected = Buffer.from(keyHex, "hex");
  const actual = (await scryptAsync(password, Buffer.from(saltHex, "hex"), expected.length)) as Buffer;
  return timingSafeEqual(actual, expected);
}

export async function listUsers(): Promise<User[]> {
  return users.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const u = users.find((u) => u.id === id);
  return u && toUser(u);
}

export async function getUserByEmail(email: string): Promise<User | undefined> {
  const e = normalizeEmail(email);
  const u = users.find((u) => u.email === e);
  return u && toUser(u);
}

export class EmailTakenError extends Error {}

export async function createUser(input: {
  email: string;
  name: string;
  password: string;
}): Promise<User> {
  const email = normalizeEmail(input.email);
  if (users.some((u) => u.email === email)) throw new EmailTakenError();
  const record: UserRecord = {
    id: randomUUID(),
    email,
    name: input.name.trim() || email.split("@")[0],
    createdAt: new Date().toISOString().slice(0, 10),
    passwordHash: await hashPassword(input.password),
  };
  users.push(record);
  return toUser(record);
}

// Returns the user if the email/password pair is valid, otherwise undefined.
export async function verifyCredentials(
  email: string,
  password: string,
): Promise<User | undefined> {
  const u = users.find((u) => u.email === normalizeEmail(email));
  // Hash even for unknown users so response time doesn't reveal which emails exist.
  const ok = await checkPassword(password, u?.passwordHash ?? DUMMY_HASH);
  return u?.passwordHash && ok ? toUser(u) : undefined;
}
const DUMMY_HASH = `${"00".repeat(16)}:${"00".repeat(64)}`;

// Finds or creates the user for a Google account. Returns undefined if the sign-in must be refused.
export async function findOrCreateGoogleUser(profile: {
  googleId: string;
  email: string;
  emailVerified: boolean;
  name?: string | null;
}): Promise<User | undefined> {
  const byGoogleId = users.find((u) => u.googleId === profile.googleId);
  if (byGoogleId) return toUser(byGoogleId);

  if (!profile.emailVerified) return undefined;
  const email = normalizeEmail(profile.email);
  const existing = users.find((u) => u.email === email);
  if (existing) {
    // Never merge into a password account: its owner may not be the Google account holder
    // (sign-up doesn't verify email), so linking would allow account takeover.
    if (existing.passwordHash) return undefined;
    existing.googleId = profile.googleId;
    return toUser(existing);
  }
  const record: UserRecord = {
    id: randomUUID(),
    email,
    name: profile.name?.trim() || email.split("@")[0],
    createdAt: new Date().toISOString().slice(0, 10),
    googleId: profile.googleId,
  };
  users.push(record);
  return toUser(record);
}

export async function getCurrentUser(): Promise<User | undefined> {
  const { auth } = await import("@/auth");
  const session = await auth();
  return session?.user?.id ? getUser(session.user.id) : undefined;
}
